    char *content = NULL;
    size_t content_size = 0;
    char ch;
    while ((ch = fgetc(file)) != EOF) {
        content = realloc(content, content_size + 1);
        content[content_size++] = ch;
    }

    // Close the file
    fclose(file);

    // Null-terminate the content
    content = realloc(content, content_size + 1);
    content[content_size] = '\0';
    free(empty_result);
    return content;
}

